public sealed partial class AlertPanel:UserControl {
 public event EventHandler WatchVideoRequested;
 readonly TextBox latitude=new TextBox(),longitude=new TextBox(),token=new TextBox{UseSystemPasswordChar=true},chat=new TextBox();readonly NumericUpDown radius=new NumericUpDown{Minimum=1,Maximum=1000,Value=20},poll=new NumericUpDown{Minimum=5,Maximum=3600,Value=30},age=new NumericUpDown{Minimum=1,Maximum=1440,Value=15};readonly DataGridView feeds=new DataGridView();readonly TextBox log=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Font=new Font("Consolas",10)};readonly Button start=new Button{Text="Start alerts"},check=new Button{Text="Check feeds (no sends)"},stop=new Button{Text="Stop",Enabled=false},save=new Button{Text="Save feed settings"};readonly Label status=new Label{Text="Stopped · enter your details to begin",Dock=DockStyle.Fill};Process worker;bool closing;readonly string stateFolder;
 public AlertPanel():this(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Aster","AirDefense")){}
 public AlertPanel(string folder){stateFolder=folder;AutoScroll=true;BackColor=Color.FromArgb(16,23,34);ForeColor=Color.FromArgb(232,240,250);Font=new Font("Segoe UI",10);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),MinimumSize=new Size(850,730),ColumnCount=1,RowCount=8};foreach(int h in new[]{55,62,195,30,170,48,32})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));Controls.Add(layout);layout.Controls.Add(new Label{Text="Your nearby alerts",Font=new Font("Segoe UI",25,FontStyle.Bold),AutoSize=true},0,0);layout.Controls.Add(new Label{Text="Nearby public advisories, delivered to your phone. No feeds are active until you start.\r\nPublic reports may be delayed or incomplete. Keep using official emergency alerts.",Dock=DockStyle.Fill},0,1);var fields=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=4,RowCount=4};for(int i=0;i<4;i++)fields.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,25));layout.Controls.Add(fields,0,2);AddField(fields,"Home latitude",latitude,0,0);AddField(fields,"Home longitude",longitude,1,0);AddField(fields,"Radius (km)",radius,2,0);AddField(fields,"Poll interval (seconds)",poll,3,0);AddField(fields,"Telegram bot token",token,0,1);AddField(fields,"Telegram chat ID",chat,1,1);AddField(fields,"Maximum report age (minutes)",age,2,1);var privacy=new Label{Text="Your home preset is stored locally in home-location.json. Telegram details are session-only.",Dock=DockStyle.Fill,Font=new Font("Segoe UI",9)};fields.Controls.Add(privacy,0,3);fields.SetColumnSpan(privacy,4);SetupLocation(fields);layout.Controls.Add(new Label{Text="FEEDS · HTTPS URLs or Telegram @channel · choose telegram format for channels",Dock=DockStyle.Fill},0,3);feeds.Dock=DockStyle.Fill;feeds.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;feeds.BackgroundColor=Color.FromArgb(24,36,53);feeds.RowHeadersWidth=30;feeds.AllowUserToAddRows=true;feeds.AllowUserToDeleteRows=true;feeds.DefaultCellStyle.BackColor=Color.FromArgb(24,36,53);feeds.DefaultCellStyle.ForeColor=ForeColor;feeds.DefaultCellStyle.SelectionBackColor=Color.FromArgb(40,74,93);feeds.Columns.Add("name","Source name");var format=new DataGridViewComboBoxColumn{Name="format",HeaderText="Format",FillWeight=45};format.Items.AddRange("rss","geojson","json","telegram");feeds.Columns.Add(format);feeds.Columns.Add("url","HTTPS feed URL / Telegram @channel");feeds.Columns[2].FillWeight=230;feeds.DefaultValuesNeeded+=(s,e)=>e.Row.Cells[1].Value="rss";feeds.DataError+=(s,e)=>{e.ThrowException=false;};layout.Controls.Add(feeds,0,4);var actions=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};foreach(var b in new[]{save,check,start,stop}){b.AutoSize=true;b.Height=34;b.BackColor=Color.FromArgb(32,49,72);b.ForeColor=ForeColor;b.FlatStyle=FlatStyle.Flat;actions.Controls.Add(b);}var youtube=new Button{Text="YouTube player",AccessibleName="Watch your linked video inside the Air Defense feed",AutoSize=true,Height=34,BackColor=Color.FromArgb(32,49,72),ForeColor=ForeColor,FlatStyle=FlatStyle.Flat};youtube.Click+=(s,e)=>{var handler=WatchVideoRequested;if(handler!=null)handler(this,EventArgs.Empty);};actions.Controls.Add(youtube);layout.Controls.Add(actions,0,5);layout.Controls.Add(status,0,6);log.BackColor=Color.FromArgb(12,18,28);log.ForeColor=ForeColor;layout.Controls.Add(log,0,7);save.Click+=(s,e)=>Guard(()=>{SaveConfiguration();Write("Feed settings saved. Location and Telegram credentials were not saved.");});check.Click+=(s,e)=>Guard(()=>Launch(true));start.Click+=(s,e)=>Guard(()=>Launch(false));stop.Click+=(s,e)=>StopWorker();LoadSettings();LoadHomeLocation(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"home-location.json"));Write("Choose real providers. Supported: GeoRSS, GeoJSON, JSON, or public Telegram channels. No alerts are active.");}
 void AddField(TableLayoutPanel grid,string caption,Control input,int col,int row){var box=new Panel{Dock=DockStyle.Fill,Height=48};box.Controls.Add(new Label{Text=caption,Dock=DockStyle.Top,Height=22,Font=new Font("Segoe UI",9)});input.Dock=DockStyle.Bottom;input.AccessibleName=caption;box.Controls.Add(input);grid.Controls.Add(box,col,row);}
 void Guard(Action action){try{action();}catch(Exception ex){MessageBox.Show(this,ex is ArgumentException?ex.Message:"Could not complete this action. Check file access and the bundled runtime.","Aster alerts");}}
 void Write(string message){if(log.TextLength>60000)log.Text=log.Text.Substring(log.TextLength-30000);log.AppendText(message+Environment.NewLine);}
 void Dispatch(Action action){if(closing||IsDisposed||!IsHandleCreated)return;try{BeginInvoke(action);}catch(InvalidOperationException){}}
 public static double Coordinate(string text,double min,double max){double value;if(!double.TryParse(text,NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value)||value<min||value>max)throw new ArgumentException("Enter valid coordinates using a decimal point. Latitude: -90 to 90. Longitude: -180 to 180.");return value;}
 public static string NormalizeChannel(string input){var match=System.Text.RegularExpressions.Regex.Match(input.Trim(),@"^(?:https://t\.me/(?:s/)?)?@?([A-Za-z][A-Za-z0-9_]{3,31})/?$",System.Text.RegularExpressions.RegexOptions.IgnoreCase);if(!match.Success)throw new ArgumentException("Enter a public channel username such as @channelname or its https://t.me/s/channelname URL. Private invites and post links are not supported.");return "https://t.me/s/"+match.Groups[1].Value.ToLowerInvariant();}
 Config ReadForm(){feeds.EndEdit();var cfg=new Config();cfg.air_defense_feed.radius_km=(double)radius.Value;cfg.air_defense_feed.poll_seconds=(double)poll.Value;cfg.air_defense_feed.max_age_seconds=(double)age.Value*60;var names=new HashSet<string>(StringComparer.Ordinal);foreach(DataGridViewRow row in feeds.Rows){if(row.IsNewRow)continue;string name=Convert.ToString(row.Cells[0].Value).Trim(),type=Convert.ToString(row.Cells[1].Value),url=Convert.ToString(row.Cells[2].Value).Trim();if(type=="telegram")url=NormalizeChannel(url);Uri uri;if(!System.Text.RegularExpressions.Regex.IsMatch(name,"^[A-Za-z0-9 _.-]{1,60}$")||!names.Add(name))throw new ArgumentException("Give each feed a unique simple source name (letters, numbers, spaces, periods, hyphens)." );if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.UserInfo!=""||uri.Fragment!=""||uri.Host.EndsWith(".invalid"))throw new ArgumentException("Enter a real HTTPS feed URL without a username, password or fragment.");if(!new[]{"rss","geojson","json","telegram"}.Contains(type))throw new ArgumentException("Choose rss, geojson, json or telegram for each feed.");cfg.air_defense_feed.sources.Add(new Feed{name=name,format=type,url=url});}if(cfg.air_defense_feed.sources.Count<1||cfg.air_defense_feed.sources.Count>20)throw new ArgumentException("Add between 1 and 20 real feed URLs.");if(cfg.air_defense_feed.sources.Any(f=>f.format=="telegram")&&poll.Value<30)throw new ArgumentException("Telegram previews require a polling interval of at least 30 seconds.");return cfg;}
 void SaveConfiguration(){var cfg=ReadForm();Directory.CreateDirectory(stateFolder);string path=Path.Combine(stateFolder,"config.json"),temp=path+".tmp";File.WriteAllText(temp,new JavaScriptSerializer().Serialize(cfg));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
 void LoadSettings(){string path=Path.Combine(stateFolder,"config.json");if(!File.Exists(path))return;try{var cfg=new JavaScriptSerializer().Deserialize<Config>(File.ReadAllText(path));var s=cfg.air_defense_feed;radius.Value=Math.Max(1,Math.Min(1000,(decimal)s.radius_km));poll.Value=Math.Max(5,Math.Min(3600,(decimal)s.poll_seconds));age.Value=Math.Max(1,Math.Min(1440,(decimal)s.max_age_seconds/60));foreach(var f in s.sources.Take(20))feeds.Rows.Add(f.name,f.format,f.url);}catch{Write("Saved feed settings could not be read. Enter them again to replace the configuration.");}}
 void Launch(bool dry){if(worker!=null)throw new ArgumentException("Stop the current monitor first.");CancelLocation();double lat=Coordinate(latitude.Text,-90,90),lon=Coordinate(longitude.Text,-180,180);if(!dry&&(!System.Text.RegularExpressions.Regex.IsMatch(token.Text.Trim(),"^[0-9]+:[A-Za-z0-9_-]+$")||string.IsNullOrWhiteSpace(chat.Text)))throw new ArgumentException("Enter your Telegram bot token and chat ID before starting alerts.");string root=AppDomain.CurrentDomain.BaseDirectory,python=Path.Combine(root,"runtime","python.exe"),script=Path.Combine(root,"AirDefense","air_defense.py");if(!File.Exists(python)||!File.Exists(script))throw new ArgumentException("Extract the entire Aster folder first. Keep runtime and AirDefense next to Aster.exe.");SaveConfiguration();var info=new ProcessStartInfo{FileName=python,Arguments="-I -B -u \""+script+"\" --config \""+Path.Combine(stateFolder,"config.json")+"\""+(dry?" --dry-run --once":""),WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["ASTER_HOME_LAT"]=lat.ToString("R",CultureInfo.InvariantCulture);info.EnvironmentVariables["ASTER_HOME_LON"]=lon.ToString("R",CultureInfo.InvariantCulture);info.EnvironmentVariables["ASTER_TELEGRAM_TOKEN"]=token.Text.Trim();info.EnvironmentVariables["ASTER_TELEGRAM_CHAT_ID"]=chat.Text.Trim();var process=new Process{StartInfo=info,EnableRaisingEvents=true};process.OutputDataReceived+=(s,e)=>{if(e.Data!=null)Dispatch(()=>Write(e.Data));};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)Dispatch(()=>Write(e.Data));};process.Exited+=(s,e)=>Dispatch(()=>{if(worker!=process)return;int code=process.ExitCode;worker=null;process.Dispose();Running(false);status.Text=code==0?(dry?"Feed check finished · review results below":"Stopped"):"Stopped with an error · review results below";});worker=process;try{process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();Running(true);status.Text=dry?"Checking feeds · no messages will be sent":"Monitoring · coverage and delivery status appear below";}catch{worker=null;process.Dispose();throw;}}
 void Running(bool running){start.Enabled=check.Enabled=save.Enabled=feeds.Enabled=latitude.Enabled=longitude.Enabled=token.Enabled=chat.Enabled=radius.Enabled=poll.Enabled=age.Enabled=!running;stop.Enabled=running;locate.Enabled=!running;}
 void StopWorker(){var process=worker;worker=null;if(process!=null){try{if(!process.HasExited)process.Kill();}catch(InvalidOperationException){}finally{process.Dispose();}}if(!closing){Running(false);status.Text="Stopped · monitoring is not active";}}
